type User = { login: string; name: string; active: boolean };
function displayName(user: User): string {
  return user.active ? user.name : `${user.name} (nieaktywny)`;
}
console.log(displayName({ login: "anna", name: "Anna", active: true }));
console.log(displayName({ login: "jan", name: "Jan", active: false }));

type User = { login: string; name: string; active: boolean };
// @ts-expect-error — brakuje name i active
const incomplete: User = { login: "anna" };
const complete: User = { login: "anna", name: "Anna", active: true };

type Contact = { id: number; name: string; email?: string };
function mailLink(contact: Contact): string | null {
  return contact.email ? `mailto:${contact.email.toLowerCase()}` : null;
}
console.log(mailLink({ id: 1, name: "Anna" })); // null

type Contact = { name: string; email?: string };
function emailLabel(contact: Contact): string { return contact.email ?? "Brak"; }
console.log(emailLabel({ name: "Anna" })); // Brak
console.log(emailLabel({ name: "Anna", email: "" })); // pusty napis

type Contact = { readonly id: number; name: string };
const contact: Contact = { id: 1, name: "Anna" };
contact.name = "Anna Nowak";
function typeCheckOnly() {
  // @ts-expect-error — id jest readonly
  contact.id = 2;
}

type User = { readonly profile: { name: string } };
const user: User = { profile: { name: "Anna" } };
user.profile.name = "Anna Nowak";
console.log(user.profile.name);
// Nie można przypisać nowego user.profile przez ten typ, ale name pozostaje zmienne.

