type TicketStatus = "OPEN" | "IN_PROGRESS" | "CLOSED";
type TicketPriority = "LOW" | "MEDIUM" | "HIGH" | "CRITICAL";
type Ticket = { id: number; title: string; description: string; status: TicketStatus; priority: TicketPriority; assignee: string | null; createdAt: string; tags: string[] };
