type TicketComment = BaseEntity & { ticketId: number; author: string; text: string };
const base: Ticket = { id: 1, title: "Eksport", description: "Pusty CSV", status: "OPEN", priority: "HIGH", assignee: null, createdAt: "2026-10-01", tags: ["export"] };
const tickets: Ticket[] = [
  base,
  { ...base, id: 2, title: "Login", status: "IN_PROGRESS", assignee: "anna", tags: ["auth"] },
  { ...base, id: 3, title: "API", status: "CLOSED", tags: ["api"] },
  { ...base, id: 4, title: "Motyw", priority: "LOW", tags: ["ui"] },
