];
const labels: Record<TicketStatus, string> = { OPEN: "Otwarty", IN_PROGRESS: "W toku", CLOSED: "Zamknięty" };
function typeCheckOnly() {
  // @ts-expect-error — DONE nie należy do TicketStatus
  const wrong: TicketStatus = "DONE";
}
console.log(tickets.length, labels.OPEN); // 5 Otwarty

